corrected_code:
@login_required
def download_patient_lab_pdf(request, report_uuid):
    report = get_object_or_404(LaboratoryReport, uuid=report_uuid)
    is_patient = report.patient == request.user
    is_attending_doctor = report.ordering_physician == request.user
    if not (is_patient or is_attending_doctor):
        raise PermissionDenied("Access to this diagnostic report is restricted.")
    return FileResponse(
        report.pdf_document.open('rb'),
        content_type='application/pdf',
        as_attachment=True,
        filename=f"lab_{report.accession_number}.pdf"
    )
